    // BAD: Sensitive data is sent to an untrusted result receiver 
    void bad(String password) {
        Intent intent = getIntent();
        ResultReceiver rec = intent.getParcelableExtra("Receiver");
        Bundle b = new Bundle();
        b.putCharSequence("pass", password);
        rec.send(0, b); 
    }

    public static void main(String[] args) {
        SensitiveResultReceiver sr = new SensitiveResultReceiver();

        // create a ResultReceiver that prints the received data
        ResultReceiver rec = new ResultReceiver() {
            @Override
            public void send(int resultCode, Bundle data) {
                System.out.println("Result code: " + resultCode + ", pass: " + data.getCharSequence("pass"));
            }
        };

        Intent intent = new Intent();
        intent.putExtra("Receiver", rec);
        sr.setIntent(intent);

        // Invoke the bad method with a sample password
        sr.bad("secretPassword123");
    }
}

