import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class NumericCastTainted {
	public static void main(String[] args) throws IOException {
		{
			long data;

			BufferedReader readerBuffered = new BufferedReader(
					new InputStreamReader(System.in, "UTF-8"));
			String stringNumber = readerBuffered.readLine();
			if (stringNumber != null) {
				data = Long.parseLong(stringNumber.trim());
			} else {
				data = 0;
			}

			// AVOID: potential truncation if input data is very large,
			// for example 'Long.MAX_VALUE'
			int scaled = (int)data;

			//...

			// GOOD: use a guard to ensure no truncation occurs
			int scaled2;
			if (data > Integer.MIN_VALUE && data < Integer.MAX_VALUE)
				scaled2 = (int)data;
			else
				throw new IllegalArgumentException("Invalid input");
		}
	}
}

import java.util.Base64;
import java.net.URL;
import java.net.HttpURLConnection;
import java.util.Map;
import java.util.HashMap;

public class InsecureBasicAuth {
  /**
   * Minimal replacement for org.apache.http.client.methods.HttpPost to avoid
   * external dependency in this example.
   */
  private static class HttpPost {
    private final String url;
    private final Map<String, String> headers = new HashMap<>();

    public HttpPost(String url) {
      this.url = url;
    }

    public void setHeader(String name, String value) {
      headers.put(name, value);
    }

    public void addHeader(String name, String value) {
      // for simplicity, treat addHeader the same as setHeader
      headers.put(name, value);
    }

    @Override
    public String toString() {
      return "HttpPost{" +
          "url='" + url + '\'' +
          ", headers=" + headers +
          '}';
    }
  }

  /**
   * Test basic authentication with Apache HTTP request.
   */
  public void testApacheHttpRequest(String username, String password) {

    // BAD: basic authentication over HTTP
    String url = "http://www.example.com/rest/getuser.do?uid=abcdx";

    // GOOD: basic authentication over HTTPS
    url = "https://www.example.com/rest/getuser.do?uid=abcdx";

    HttpPost post = new HttpPost(url);
    post.setHeader("Accept", "application/json");
    post.setHeader("Content-type", "application/json");

    String authString = username + ":" + password;
    byte[] authEncBytes = Base64.getEncoder().encode(authString.getBytes());
    String authStringEnc = new String(authEncBytes);

    post.addHeader("Authorization", "Basic " + authStringEnc);
  }

  /**
   * Test basic authentication with Java HTTP URL connection.
   */
  public void testHttpUrlConnection(String username, String password) throws Exception {

    // BAD: basic authentication over HTTP
    String urlStr = "http://www.example.com/rest/getuser.do?uid=abcdx";

    // GOOD: basic authentication over HTTPS
    urlStr = "https://www.example.com/rest/getuser.do?uid=abcdx";

    String authString = username + ":" + password;
    String encoding = Base64.getEncoder().encodeToString(authString.getBytes("UTF-8"));
    URL url = new URL(urlStr);
    HttpURLConnection conn = (HttpURLConnection) url.openConnection();
    conn.setRequestMethod("POST");
    conn.setDoOutput(true);
    conn.setRequestProperty("Authorization", "Basic " + encoding);
  }

  public static void main(String[] args) {
    InsecureBasicAuth demo = new InsecureBasicAuth();
    // Call the Apache HTTP request test (no network I/O in this example helper)
    demo.testApacheHttpRequest("user", "pass");

    // Attempt the URL connection test but catch any exceptions to avoid crashing.
    try {
      demo.testHttpUrlConnection("user", "pass");
    } catch (Exception e) {
      // Ignore for demo purposes.
    }
  }
}

