public class LdapAuthUseLdap {
    public static void main(String[] args) {
        // BAD: LDAP authentication is used
        String ldapUrl = "ldap://ad.your-server.com:389";
        // example credentials (replace with real ones as needed)
        String ldapUserName = "cn=admin,dc=example,dc=com";
        String password = "password";

        DirContext dirContext = null;
        try {
            // Check LDAP server reachability before attempting to create InitialDirContext
            URI uri = new URI(ldapUrl);
            String host = uri.getHost();
            int port = uri.getPort() == -1 ? 389 : uri.getPort();

            // Try connecting with a short timeout to avoid long blocking or exceptions from JNDI
            try (Socket socket = new Socket()) {
                socket.connect(new InetSocketAddress(host, port), 2000);
            } catch (Exception e) {
                System.err.println("Cannot connect to LDAP server " + host + ":" + port + " - " + e.getMessage());
                return;
            }

            Hashtable<String, String> environment = new Hashtable<String, String>();
