public class IntentUriPermissionManipulation extends Activity {

    // BAD: the user-provided Intent is returned as-is
    public void dangerous() {
        Intent intent = getIntent();
        intent.putExtra("result", "resultData");
        setResult(intent);
    }

    // GOOD: a new Intent is created and returned
    public void safe() {
        Intent intent = new Intent();
        intent.putExtra("result", "resultData");
        setResult(intent);
    }

    // GOOD: the user-provided Intent is sanitized before being returned
    public void sanitized() {
        Intent intent = getIntent();
        intent.putExtra("result", "resultData");
        intent.removeFlags(
                Intent.FLAG_GRANT_WRITE_URI_PERMISSION | Intent.FLAG_GRANT_READ_URI_PERMISSION);
        setResult(intent);
    }

    // Added main to allow standalone execution
    public static void main(String[] args) {
        IntentUriPermissionManipulation activity = new IntentUriPermissionManipulation();

        // simulate calls
        activity.dangerous();
        // inspect result of dangerous
        System.out.println("Dangerous result: " + activity.getIntent().getExtra("result"));

        activity.safe();
        System.out.println("Safe result: " + activity.getIntent().getExtra("result"));

        // add flags to incoming intent to simulate permissions, then sanitize
        activity.getIntent().addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION | Intent.FLAG_GRANT_WRITE_URI_PERMISSION);
        System.out.println("Flags before sanitize: " + activity.getIntent().getFlags());
        activity.sanitized();
        System.out.println("Flags after sanitize: " + activity.getIntent().getFlags());
    }
}

