    public void warn(String format, Object... args) {
        String msg = format;
        if (args != null && args.length > 0) {
            for (Object arg : args) {
                msg = msg.replaceFirst("\\{\\}", arg == null ? "null" : escapeNewlines(arg.toString()));
            }
