// Minimal Encoder implementation with the methods used in the sample.
class Encoder {
  public String encodeForDN(String input) {
    if (input == null) return null;
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
      char c = input.charAt(i);
      // Characters that should be escaped in a DN per RFC-ish rules
      if (c == ',' || c == '+' || c == '"' || c == '\\' || c == '<' || c == '>' || c == ';' || c == '=' ) {
        sb.append('\\').append(c);
      } else {
        sb.append(c);
      }
    }
    return sb.toString();
  }

  public String encodeForLDAP(String input) {
    if (input == null) return null;
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
      char c = input.charAt(i);
      // Escape LDAP special characters: \ * ( )
      if (c == '\\' || c == '*' || c == '(' || c == ')') {
        sb.append('\\').append(c);
      } else if (c == '\0') {
        sb.append("\\00");
      } else {
        sb.append(c);
      }
    }
    return sb.toString();
  }
}

