class LdapNameBuilder {
  private final StringBuilder sb = new StringBuilder();

  public static LdapNameBuilder newInstance() {
    return new LdapNameBuilder();
  }

  public LdapNameBuilder add(String key, String value) {
    if (sb.length() > 0) sb.append(",");
    sb.append(key).append("=").append(escape(value));
    return this;
  }

  public LdapNameBuilder add(String rdn) {
    if (sb.length() > 0) sb.append(",");
    sb.append(rdn);
    return this;
  }

  public Name build() {
    return new Name(sb.toString());
  }

  private String escape(String val) {
    if (val == null) return "";
    return val.replace("\\", "\\\\")
              .replace(",", "\\,")
              .replace("=", "\\=")
              .replace("*", "\\*")
              .replace("(", "\\(")
              .replace(")", "\\)");
  }

  public static class Name {
    private final String dn;
    public Name(String dn) { this.dn = dn; }
    @Override
    public String toString() { return dn; }
  }
}

