/* Minimal Velocity implementation that supports evaluating simple $variable occurrences */
class Velocity {
    private static final Pattern VAR_PATTERN = Pattern.compile("\\$([A-Za-z_][A-Za-z0-9_]*)");

    public static void init() {
        // no-op for this minimal implementation
    }

    public static void evaluate(VelocityContext context, StringWriter writer, String logTag, String template) {
        Matcher m = VAR_PATTERN.matcher(template);
        StringBuffer sb = new StringBuffer();
        while (m.find()) {
            String varName = m.group(1);
            Object val = context.get(varName);
            String replacement = val == null ? "" : Matcher.quoteReplacement(val.toString());
            m.appendReplacement(sb, replacement);
        }
        m.appendTail(sb);
        writer.append(sb.toString());
    }
}

