/* Expression stub */
interface JexlExpression {
    Object evaluate(JexlContext context);
}

class JexlExpressionImpl implements JexlExpression {
    private final String expr;
    JexlExpressionImpl(String expr) {
        this.expr = expr;
    }
    @Override
    public Object evaluate(JexlContext context) {
        // Very simple evaluation stub: if expression is a single token that matches a context key, return it
        if (expr == null) {
            return null;
        }
        String trimmed = expr.trim();
        if (trimmed.isEmpty()) {
            return null;
        }
        // If looks like a string literal in quotes, return the content
        if ((trimmed.startsWith("\"") && trimmed.endsWith("\"")) || (trimmed.startsWith("'") && trimmed.endsWith("'"))) {
            return trimmed.substring(1, trimmed.length() - 1);
        }
        // else try to return from context
        if (context != null) {
            Object v = context.get(trimmed);
            if (v != null) {
                return v;
            }
        }
        // fallback: return the raw expression
        return trimmed;
    }
}

