public class GroovyInjectionBlocklist {
    public static class SandboxGroovyClassLoader extends ClassLoader {
        public SandboxGroovyClassLoader(ClassLoader parent) {
            super(parent);
        }

        public SandboxGroovyClassLoader() {
            super(SandboxGroovyClassLoader.class.getClassLoader());
        }

        /* override `loadClass` here to prevent loading sensitive classes, such as `java.lang.Runtime`, `java.lang.ProcessBuilder`, `java.lang.System`, etc.  */
        /* Note we must also block `groovy.transform.ASTTest`, `groovy.lang.GrabConfig` and `org.buildobjects.process.ProcBuilder` to prevent compile-time RCE. */

        public java.lang.Class<?> parseClass(String script) {
            // Return a simple static stub class that has a public no-arg constructor and a bar() method.
            return ScriptStub.class;
        }

        public static class ScriptStub {
            public Object bar() {
                return null;
            }
        }

        static void runWithSandboxGroovyClassLoader() throws Exception {
            // GOOD: route all class-loading via sand-boxing classloader.
            SandboxGroovyClassLoader classLoader = new GroovyClassLoader(new SandboxGroovyClassLoader());

            java.lang.Class<?> scriptClass = classLoader.parseClass(untrusted.getQueryString());
            Object scriptInstance = scriptClass.getDeclaredConstructor().newInstance();
            Object result = scriptClass.getDeclaredMethod("bar", new java.lang.Class[]{}).invoke(scriptInstance, new Object[]{});
        }
    }

    // Minimal stub of GroovyClassLoader so the example compiles and the instantiation works.
    public static class GroovyClassLoader extends SandboxGroovyClassLoader {
        public GroovyClassLoader(ClassLoader parent) {
            super(parent);
        }
    }

    // Minimal stub for the `untrusted` object referenced in the sample code.
    public static class Untrusted {
        public String getQueryString() {
            return "";
        }
    }

    public static final Untrusted untrusted = new Untrusted();

    public static void main(String[] args) throws Exception {
        SandboxGroovyClassLoader.runWithSandboxGroovyClassLoader();
    }
}

public class SqlConcatenated {
    public static void main(String[] args) {
        Connection connection = new Connection();

        {
            // BAD: the category might have SQL special characters in it
            String category = getCategory();
            Statement statement = connection.createStatement();
            String query1 = "SELECT ITEM,PRICE FROM PRODUCT WHERE ITEM_CATEGORY='"
                + category + "' ORDER BY PRICE";
            ResultSet results = statement.executeQuery(query1);
        }

        {
            // GOOD: use a prepared query
            String category = getCategory();
            String query2 = "SELECT ITEM,PRICE FROM PRODUCT WHERE ITEM_CATEGORY=? ORDER BY PRICE";
            PreparedStatement statement = connection.prepareStatement(query2);
            statement.setString(1, category);
            ResultSet results = statement.executeQuery();
        }
    }

    private static String getCategory() {
        return "Books";
    }

    // Simple local implementations to allow the example to run without a real JDBC driver.
    public static class Connection {
        public Statement createStatement() {
            return new Statement();
        }

        public PreparedStatement prepareStatement(String sql) {
            return new PreparedStatement(sql);
        }
    }

    public static class Statement {
        public ResultSet executeQuery(String sql) {
            System.out.println("Executing query: " + sql);
            return new ResultSet();
        }
    }

    public static class PreparedStatement extends Statement {
        private final String sql;
        private final String[] params = new String[10];

        public PreparedStatement(String sql) {
            this.sql = sql;
        }

        public void setString(int index, String value) {
            if (index >= 1 && index <= params.length) {
                params[index - 1] = value;
            }
        }

        public ResultSet executeQuery() {
            String finalSql = sql;
            int idx = finalSql.indexOf('?');
            int p = 0;
            while (idx >= 0 && p < params.length) {
                String val = params[p++];
                if (val == null) break;
                finalSql = finalSql.substring(0, idx) + "'" + val + "'" + finalSql.substring(idx + 1);
                idx = finalSql.indexOf('?');
            }
            System.out.println("Executing prepared query: " + finalSql);
            return new ResultSet();
        }
    }

    public static class ResultSet {
        // empty stub for example
    }
}

