import java.util.Hashtable;
import javax.naming.Context;
import javax.naming.InitialContext;
import javax.naming.NamingException;

interface HttpServletRequest {
  String getParameter(String name);
}

public class JndiInjection {

  public static void main(String[] args) {
    JndiInjection app = new JndiInjection();
    HttpServletRequest req = new HttpServletRequest() {
      @Override
      public String getParameter(String name) {
        // Example parameter value; in real use this would come from an HTTP request
        return "example";
      }
    };

    try {
      app.jndiLookup(req);
    } catch (NamingException e) {
      e.printStackTrace();
    }
  }

  public void jndiLookup(HttpServletRequest request) throws NamingException {
    String name = request.getParameter("name");

    Hashtable<String, String> env = new Hashtable<String, String>();
    env.put(Context.INITIAL_CONTEXT_FACTORY, "com.sun.jndi.rmi.registry.RegistryContextFactory");
    env.put(Context.PROVIDER_URL, "rmi://trusted-server:1099");
    InitialContext ctx = new InitialContext(env);

    // BAD: User input used in lookup
    ctx.lookup(name);

    // GOOD: The name is validated before being used in lookup
    if (isValid(name)) {
      ctx.lookup(name);
    } else {
      // Reject the request
    }
  }

  private boolean isValid(String name) {
    if (name == null) {
      return false;
    }
    // Basic validation: allow alphanumerics, underscore, dot and hyphen
    return name.matches("[a-zA-Z0-9_.-]+");
  }
}

