class Paths {
    public static final String MAKE_PREFIX = "/usr";
}

class Test {
    public static void main(String[] args) {
        // BAD: relative path
        String relative = "make";
        String resolved = findInPath(relative);
        if (resolved != null) {
            try {
                Runtime.getRuntime().exec(resolved);
            } catch (IOException e) {
                System.err.println("Failed to exec " + resolved + ": " + e.getMessage());
            }
        } else {
            System.err.println("Skipping '" + relative + "' - not found in PATH");
        }

        // GOOD: absolute path
        String abs = "/usr/bin/make";
        File absFile = new File(abs);
        if (absFile.exists() && absFile.canExecute()) {
            try {
                Runtime.getRuntime().exec(abs);
            } catch (IOException e) {
                System.err.println("Failed to exec " + abs + ": " + e.getMessage());
            }
        } else {
            System.err.println("Skipping '" + abs + "' - not available or not executable");
        }

        // GOOD: build an absolute path from known values
        String built = Paths.MAKE_PREFIX + "/bin/make";
        File builtFile = new File(built);
        if (builtFile.exists() && builtFile.canExecute()) {
            try {
                Runtime.getRuntime().exec(built);
            } catch (IOException e) {
                System.err.println("Failed to exec " + built + ": " + e.getMessage());
            }
        } else {
            System.err.println("Skipping '" + built + "' - not available or not executable");
        }
    }

    private static String findInPath(String name) {
        String pathEnv = System.getenv("PATH");
        if (pathEnv == null || pathEnv.isEmpty()) {
            return null;
        }
        for (String dir : pathEnv.split(File.pathSeparator)) {
            File f = new File(dir, name);
            if (f.exists() && f.canExecute()) {
                return f.getAbsolutePath();
            }
        }
        return null;
    }
}

