public class ConditionalBypass {

    public static void main(String[] args) {
        BadVersion bad = new BadVersion();
        GoodVersion good = new GoodVersion();

        System.out.println("Bad version login result: " + bad.doLogin("user", "pass"));
        System.out.println("Good version login result: " + good.doLogin("admin", "adminpass"));
    }

    public static class BadVersion {
        public boolean doLogin(String user, String password) {
            Cookie adminCookie = getCookies()[0];

            // BAD: login is executed only if the value of 'adminCookie' is 'false', 
            // but 'adminCookie' is controlled by the user
            if(adminCookie.getValue()=="false")
                return login(user, password);

            return true;
        }

        private Cookie[] getCookies() {
            // For demonstration purposes return a cookie controlled value.
            return new Cookie[] { new Cookie("isAdmin", "false") };
        }

        private boolean login(String user, String password) {
            // Dummy authentication logic
            return Objects.equals(user, "user") && Objects.equals(password, "pass");
        }
    }

    public static class GoodVersion {
        public boolean doLogin(String user, String password) {
            Cookie adminCookie = getCookies()[0];

            // GOOD: use server-side information based on the credentials to decide
            // whether user has privileges
            boolean isAdmin = queryDbForAdminStatus(user, password);
            if(!isAdmin)
                return login(user, password);

            return true;
        }

        private Cookie[] getCookies() {
            // For demonstration purposes return a cookie controlled value.
            return new Cookie[] { new Cookie("isAdmin", "false") };
        }

        private boolean login(String user, String password) {
            // Dummy authentication logic
            return Objects.equals(user, "user") && Objects.equals(password, "pass");
        }

        private boolean queryDbForAdminStatus(String user, String password) {
            // Dummy server-side admin check
            return Objects.equals(user, "admin") && Objects.equals(password, "adminpass");
        }
    }
}

