            Intent forwardIntent = (Intent) getIntent().getParcelableExtra("forward_intent");
            if (forwardIntent != null) {
                startActivity(forwardIntent);
            }
        }

        // GOOD: The destination component is checked before launching it
        {
            Intent forwardIntent = (Intent) getIntent().getParcelableExtra("forward_intent");
            if (forwardIntent != null) {
                ComponentName destinationComponent = forwardIntent.resolveActivity(getPackageManager());
                if (destinationComponent != null &&
                    destinationComponent.getPackageName().equals("safe.package") &&
                    destinationComponent.getClassName().equals("SafeClass")) {
                    startActivity(forwardIntent);
                }
            }
        }

        // GOOD: The component that sent the Intent is checked before launching the destination component
        {
            Intent forwardIntent = (Intent) getIntent().getParcelableExtra("forward_intent");
            ComponentName originComponent = getCallingActivity();
            if (forwardIntent != null && originComponent != null) {
                if (originComponent.getPackageName().equals("trusted.package") &&
                    originComponent.getClassName().equals("TrustedClass")) {
                    startActivity(forwardIntent);
                }
            }
        }
    }

    public static void main(String[] args) {
        AndroidIntentRedirectionSample sample = new AndroidIntentRedirectionSample();

        // Prepare test data to avoid NullPointerException
        Intent userIntent = new Intent();
        // Set a dummy forward_intent for getParcelableExtra to return
        Intent forwardIntent = new Intent();
        forwardIntent.setResolvedActivity(new ComponentName("safe.package", "SafeClass"));
        userIntent.setParcelableExtra(forwardIntent);
        sample.getIntent().setParcelableExtra(forwardIntent);

        // Set package manager (dummy)
        sample.setPackageManager(new Object());

        // Set calling activity
        sample.setCallingActivity(new ComponentName("trusted.package", "TrustedClass"));

        // Also set the intent's extra so getParcelableExtra works as expected
        sample.getIntent().setParcelableExtra(forwardIntent);

        sample.onCreate(new Bundle());
    }
}

