class JwtParser {
    public Jwt<Header, String> parse(String token) {
        return new Jwt<>(new Header(), token);
    }

    @SuppressWarnings("unchecked")
    public <T> T parse(String token, JwtHandlerAdapter<T> handler) {
        T result = null;
        try {
            result = handler.onPlaintextJwt(new Jwt<>(new Header(), token));
            if (result != null) return result;
        } catch (AbstractMethodError | RuntimeException ignored) {
        }

        try {
            result = handler.onPlaintextJws(new Jws<>(token));
            if (result != null) return result;
        } catch (AbstractMethodError | RuntimeException ignored) {
        }

        return result;
    }

    public Jws<String> parseClaimsJws(String token) {
        return new Jws<>(token);
    }
}

